import { ApplicationConfig } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideSkewRecovery } from '@braidlabs/angular-router';

// Generated by `skew-stamp` (see package.json scripts). Exports
// BUILD_IDENTITY = { buildId, builtAt }. `builtAt` is what makes
// `staleOrigin` detectable — timestamps order builds, ids alone can't.
import { BUILD_IDENTITY } from './generated/build-id';

import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideRouter(routes),

    provideSkewRecovery({
      identity: BUILD_IDENTITY,

      // Emitted by the postbuild `skew-stamp` run. MUST be served with
      // `Cache-Control: no-store` — a cached manifest makes the probe
      // compare against a stale snapshot and defeats the whole mechanism.
      manifestUrl: '/skew-manifest.json',

      // Default strategy, stated explicitly: when a lazy chunk 404s because
      // a new deploy replaced the hashed filenames, reload *at the target
      // URL* (location.assign(targetUrl)). Angular defers the URL update
      // until navigation succeeds, so a plain reload would lose where the
      // user was trying to go; reload-at-target preserves the intent.
      onStaleChunk: 'reload-at-target',

      // Hard requirement #1 — no reload loops. This is enforced in two
      // layers, both built in:
      //   1. Before any auto-reload, the recovery probes the manifest and
      //      REFUSES to reload when the origin is *older* than the running
      //      client (`staleOrigin`, e.g. a CDN region still serving the old
      //      index.html). Reloading there would fetch the same stale bundle
      //      forever — exactly the incident we had. It degrades to 'notify'
      //      and the banner takes over. Same for `unreachable` (offline):
      //      reloading would land on an error page.
      //   2. Even for legitimate staleClient cases, auto-recoveries are
      //      capped per session. One automatic attempt; after that it's the
      //      banner and a human decision.
      maxRecoveries: 1,

      // Hard requirement #2 — never reload over a half-filled form.
      // Components with dirty state register via trackUnsavedWork()
      // (see editor-shell.component.ts). While any tracker reports unsaved
      // work, recovery degrades from reloading to 'notify', and the banner
      // (update-banner.component.ts) lets the user choose the moment.
      // true is the default; stated explicitly because it's load-bearing.
      respectUnsavedWork: true,
    }),
  ],
};
